class Solution:
    def highestRankedKItems(self, grid: List[List[int]], pricing: List[int], start: List[int], k: int) -> List[List[int]]:
        m, n = len(grid), len(grid[0])
        low, high = pricing
        sr, sc = start
        q = collections.deque([(sr, sc, 0)])
        visited = [[False] * n for _ in range(m)]
        visited[sr][sc] = True
        items = []
        if low <= grid[sr][sc] <= high:
            items.append((0, grid[sr][sc], sr, sc))

        while q:
            r, c, d = q.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and not visited[nr][nc] and grid[nr][nc] != 0:
                    visited[nr][nc] = True
                    q.append((nr, nc, d + 1))
                    if low <= grid[nr][nc] <= high:
                        items.append((d + 1, grid[nr][nc], nr, nc))
        items.sort()
        return [[r, c] for _, _, r, c in items[:k]]

class Solution {
public:
    vector<vector<int>> highestRankedKItems(vector<vector<int>>& grid, vector<int>& pricing, vector<int>& start, int k) {
        int m = grid.size(), n = grid[0].size();
        int low = pricing[0], high = pricing[1];
        int sr = start[0], sc = start[1];
        queue<tuple<int, int, int>> q;
        q.push({sr, sc, 0});
        vector<vector<bool>> visited(m, vector<bool>(n, false));
        visited[sr][sc] = true;
        vector<tuple<int, int, int, int>> items;
        if (grid[sr][sc] >= low && grid[sr][sc] <= high) {
            items.push_back({0, grid[sr][sc], sr, sc});
        }
        int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
        while (!q.empty()) {
            auto [r, c, d] = q.front();
            q.pop();
            for (auto& dir : dirs) {
                int nr = r + dir[0], nc = c + dir[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] != 0) {
                    visited[nr][nc] = true;
                    q.push({nr, nc, d + 1});
                    if (grid[nr][nc] >= low && grid[nr][nc] <= high) {
                        items.push_back({d + 1, grid[nr][nc], nr, nc});
                    }
                }
            }
        }
        sort(items.begin(), items.end());
        vector<vector<int>> res;
        int limit = min((int)items.size(), k);
        for (int i = 0; i < limit; i++) {
            auto [d, p, r, c] = items[i];
            res.push_back({r, c});
        }
        return res;
    }
};

class Solution {
    public List<List<Integer>> highestRankedKItems(int[][] grid, int[] pricing, int[] start, int k) {
        int m = grid.length, n = grid[0].length;
        int low = pricing[0], high = pricing[1];
        int sr = start[0], sc = start[1];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sr, sc, 0});
        boolean[][] visited = new boolean[m][n];
        visited[sr][sc] = true;
        List<int[]> items = new ArrayList<>();
        if (grid[sr][sc] >= low && grid[sr][sc] <= high) {
            items.add(new int[]{0, grid[sr][sc], sr, sc});
        }
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], d = cur[2];
            for (int[] dir : dirs) {
                int nr = r + dir[0], nc = c + dir[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] != 0) {
                    visited[nr][nc] = true;
                    q.offer(new int[]{nr, nc, d + 1});
                    if (grid[nr][nc] >= low && grid[nr][nc] <= high) {
                        items.add(new int[]{d + 1, grid[nr][nc], nr, nc});
                    }
                }
            }
        }
        items.sort((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            if (a[1] != b[1]) return Integer.compare(a[1], b[1]);
            if (a[2] != b[2]) return Integer.compare(a[2], b[2]);
            return Integer.compare(a[3], b[3]);
        });
        List<List<Integer>> res = new ArrayList<>();
        int limit = Math.min(items.size(), k);
        for (int i = 0; i < limit; i++) {
            int[] it = items.get(i);
            res.add(Arrays.asList(it[2], it[3]));
        }
        return res;
    }
}

var highestRankedKItems = function(grid, pricing, start, k) {
    const m = grid.length, n = grid[0].length;
    const [low, high] = pricing;
    const [sr, sc] = start;
    const q = [[sr, sc, 0]];
    const visited = Array.from({ length: m }, () => new Uint8Array(n));
    visited[sr][sc] = 1;
    const items = [];
    if (grid[sr][sc] >= low && grid[sr][sc] <= high) {
        items.push([0, grid[sr][sc], sr, sc]);
    }
    let head = 0;
    const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
    while (head < q.length) {
        const [r, c, d] = q[head++];
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] !== 0) {
                visited[nr][nc] = 1;
                q.push([nr, nc, d + 1]);
                if (grid[nr][nc] >= low && grid[nr][nc] <= high) {
                    items.push([d + 1, grid[nr][nc], nr, nc]);
                }
            }
        }
    }
    items.sort((a, b) => {
        if (a[0] !== b[0]) return a[0] - b[0];
        if (a[1] !== b[1]) return a[1] - b[1];
        if (a[2] !== b[2]) return a[2] - b[2];
        return a[3] - b[3];
    });
    return items.slice(0, k).map(it => [it[2], it[3]]);
};
